import java.lang.reflect.*;import java.sql.*;import java.util.*;import restaurante.config.DatabaseInitializer;
public class VerificaInicializacion {
 static boolean existente;static int createDb,ddl,semillas;
 static Object def(Class<?>t){if(!t.isPrimitive())return null;if(t==boolean.class)return false;if(t==int.class)return 0;if(t==long.class)return 0L;return null;}
 @SuppressWarnings("unchecked")static <T>T p(Class<T>t,InvocationHandler h){return(T)Proxy.newProxyInstance(t.getClassLoader(),new Class<?>[]{t},h);}
 static Connection c(){return p(Connection.class,(o,m,a)->{switch(m.getName()){case "getCatalog":return "restaurante_intermedio";case "getMetaData":return p(DatabaseMetaData.class,(x,k,b)->{if(k.getName().equals("getTables")){int[] i={0};return p(ResultSet.class,(z,j,v)->j.getName().equals("next")?existente&&i[0]++==0:def(j.getReturnType()));}return def(k.getReturnType());});case "createStatement":return p(Statement.class,(x,k,b)->{if(k.getName().equals("executeUpdate")){createDb++;return 1;}if(k.getName().equals("execute")){String sql=((String)b[0]).toUpperCase(Locale.ROOT);if(sql.contains("CREATE TABLE"))ddl++;if(sql.contains("INSERT IGNORE"))semillas++;return false;}return def(k.getReturnType());});default:return def(m.getReturnType());}});}
 static class D implements Driver{public Connection connect(String u,Properties p){return c();}public boolean acceptsURL(String u){return u.startsWith("jdbc:mysql:");}public DriverPropertyInfo[] getPropertyInfo(String u,Properties p){return new DriverPropertyInfo[0];}public int getMajorVersion(){return 1;}public int getMinorVersion(){return 0;}public boolean jdbcCompliant(){return false;}public java.util.logging.Logger getParentLogger(){return java.util.logging.Logger.getGlobal();}}
 static void verificar(boolean existe){existente=existe;createDb=ddl=semillas=0;DatabaseInitializer.inicializar();if(createDb!=1||ddl!=14||(existe?semillas!=0:semillas!=6))throw new AssertionError("create="+createDb+" ddl="+ddl+" seed="+semillas);System.out.println(existe?"OK: esquema existente sin reinsertar semillas":"OK: esquema vacío crea tablas y datos iniciales");}
 public static void main(String[]a)throws Exception{Class.forName("com.mysql.cj.jdbc.Driver");for(Enumeration<Driver>d=DriverManager.getDrivers();d.hasMoreElements();)DriverManager.deregisterDriver(d.nextElement());DriverManager.registerDriver(new D());verificar(false);verificar(true);}
}
